  "concept": "SQL SELECT, JOIN, LEFT JOIN, GROUP BY, HAVING and ORDER BY with sqlite3",
  "task": "`make_db()` (already written) creates an in-memory SQLite database with two tables: `customers(id, name, city)` and `orders(id, customer_id, amount)`.\nWrite `revenue_by_city(conn, min_total=0)` that runs ONE SQL query and returns a list of `(city, total_amount, num_orders)` tuples: JOIN `orders` to `customers` on `orders.customer_id = customers.id`, GROUP BY city, keep only cities whose total is at least `min_total` (use `HAVING` with a `?` placeholder) and ORDER BY total, highest first.\nGet the rows with `conn.execute(sql, (min_total,)).fetchall()`.\nThen write `customers_without_orders(conn)` that returns a list of the names of customers who never ordered, sorted A to Z. Hint: a `LEFT JOIN` keeps every customer and fills the order columns with `NULL` when there is no match.\nExample: `revenue_by_city(make_db())[0]` is `('Mumbai', 5300, 3)`.",
  "starter": "import sqlite3\n\ndef make_db():\n    \"\"\"Create the sample database - do not edit.\"\"\"\n    conn = sqlite3.connect(\":memory:\")\n    conn.execute(\"CREATE TABLE customers (id INTEGER PRIMARY KEY, name TEXT, city TEXT)\")\n    conn.execute(\"CREATE TABLE orders (id INTEGER PRIMARY KEY, customer_id INTEGER, amount INTEGER)\")\n    conn.executemany(\"INSERT INTO customers VALUES (?, ?, ?)\", [\n        (1, \"Aarav\", \"Mumbai\"), (2, \"Diya\", \"Delhi\"), (3, \"Kabir\", \"Mumbai\"),\n        (4, \"Ananya\", \"Chennai\"), (5, \"Rohan\", \"Delhi\"), (6, \"Ishita\", \"Kolkata\"),\n        (7, \"Vihaan\", \"Pune\"),\n    ])\n    conn.executemany(\"INSERT INTO orders VALUES (?, ?, ?)\", [\n        (1, 1, 2500), (2, 2, 1200), (3, 3, 1800), (4, 1, 1000),\n        (5, 4, 700), (6, 5, 900), (7, 2, 400),\n    ])\n    return conn\n\ndef revenue_by_city(conn, min_total=0):\n    sql = \"\"\"\n        SELECT customers.city, SUM(orders.amount), COUNT(*)\n        FROM orders\n        -- TODO: JOIN customers ON ...\n        -- TODO: GROUP BY ..., HAVING ... >= ?, ORDER BY ... DESC\n    \"\"\"\n    # TODO: return conn.execute(sql, (min_total,)).fetchall()\n    pass\n\ndef customers_without_orders(conn):\n    # TODO: LEFT JOIN, then keep rows where the order id IS NULL\n    pass\n\n# Try it: you can run any SQL you like here\nconn = make_db()\nprint(conn.execute(\"SELECT * FROM customers\").fetchall())\nprint(revenue_by_city(conn))\n",
  "solution": "import sqlite3\n\ndef make_db():\n    \"\"\"Create the sample database - do not edit.\"\"\"\n    conn = sqlite3.connect(\":memory:\")\n    conn.execute(\"CREATE TABLE customers (id INTEGER PRIMARY KEY, name TEXT, city TEXT)\")\n    conn.execute(\"CREATE TABLE orders (id INTEGER PRIMARY KEY, customer_id INTEGER, amount INTEGER)\")\n    conn.executemany(\"INSERT INTO customers VALUES (?, ?, ?)\", [\n        (1, \"Aarav\", \"Mumbai\"), (2, \"Diya\", \"Delhi\"), (3, \"Kabir\", \"Mumbai\"),\n        (4, \"Ananya\", \"Chennai\"), (5, \"Rohan\", \"Delhi\"), (6, \"Ishita\", \"Kolkata\"),\n        (7, \"Vihaan\", \"Pune\"),\n    ])\n    conn.executemany(\"INSERT INTO orders VALUES (?, ?, ?)\", [\n        (1, 1, 2500), (2, 2, 1200), (3, 3, 1800), (4, 1, 1000),\n        (5, 4, 700), (6, 5, 900), (7, 2, 400),\n    ])\n    return conn\n\ndef revenue_by_city(conn, min_total=0):\n    sql = \"\"\"\n        SELECT c.city, SUM(o.amount) AS total, COUNT(*) AS num_orders\n        FROM orders AS o\n        JOIN customers AS c ON o.customer_id = c.id\n        GROUP BY c.city\n        HAVING SUM(o.amount) >= ?\n        ORDER BY total DESC\n    \"\"\"\n    return conn.execute(sql, (min_total,)).fetchall()\n\ndef customers_without_orders(conn):\n    sql = \"\"\"\n        SELECT c.name\n        FROM customers AS c\n        LEFT JOIN orders AS o ON o.customer_id = c.id\n        WHERE o.id IS NULL           -- no matching order was found\n        ORDER BY c.name\n    \"\"\"\n    return [row[0] for row in conn.execute(sql).fetchall()]\n\n# Try it: you can run any SQL you like here\nconn = make_db()\nprint(conn.execute(\"SELECT * FROM customers\").fetchall())\nprint(revenue_by_city(conn))             # [('Mumbai', 5300, 3), ('Delhi', 2500, 3), ('Chennai', 700, 1)]\nprint(customers_without_orders(conn))    # ['Ishita', 'Vihaan']\n",
  "tests": "check(\"revenue_by_city(make_db())[0] is ('Mumbai', 5300, 3)\", lambda: revenue_by_city(make_db())[0] == ('Mumbai', 5300, 3), \"JOIN customers ON orders.customer_id = customers.id, then GROUP BY customers.city.\")\ncheck(\"all cities with orders, highest total first\", lambda: revenue_by_city(make_db()) == [('Mumbai', 5300, 3), ('Delhi', 2500, 3), ('Chennai', 700, 1)], \"ORDER BY the SUM in descending order (DESC).\")\ncheck(\"cities with no orders (Kolkata, Pune) do not appear\", lambda: all(row[0] not in ('Kolkata', 'Pune') for row in revenue_by_city(make_db())), \"A normal (inner) JOIN only keeps customers who have orders.\")\ncheck(\"min_total=1000 keeps only Mumbai and Delhi\", lambda: revenue_by_city(make_db(), 1000) == [('Mumbai', 5300, 3), ('Delhi', 2500, 3)], \"Filter groups with HAVING SUM(orders.amount) >= ? and pass (min_total,) to execute.\")\ncheck(\"a very high min_total gives an empty list\", lambda: revenue_by_city(make_db(), 100000) == [], \"fetchall() returns [] when no group passes the HAVING filter.\")\ncheck(\"customers_without_orders(make_db()) is ['Ishita', 'Vihaan']\", lambda: customers_without_orders(make_db()) == ['Ishita', 'Vihaan'], \"LEFT JOIN orders and keep the rows WHERE orders.id IS NULL, ORDER BY name.\")\ncheck(\"customers_without_orders returns plain names, not tuples\", lambda: all(isinstance(n, str) for n in customers_without_orders(make_db())) and len(customers_without_orders(make_db())) == 2, \"Each row from fetchall() is a tuple like ('Ishita',) - take row[0].\")",
